function Status({value}) {
  const s=String(value??"UNKNOWN").toUpperCase();
  const tone=["APPROVED","COMPLETED","PRESENT","SERVICEABLE","PASS","ISSUED","ACTIVE"].includes(s)?"good":["PROPOSED","PENDING","REQUESTED","LATE","NEEDS_REPAIR","DRAFT"].includes(s)?"warn":["REJECTED","CANCELLED","ABSENT","DAMAGED","LOST","FAIL","INACTIVE"].includes(s)?"bad":"neutral";
  return <span className={"status "+tone}><i/>{human(s)}</span>;
}
